// Optional ORAVA simulation. Original collision bodies, scoring and level data stay authoritative.
export const ORAVA_FOOD={311:'bonus-halusky',117:'pickup-pirohy',115:'pickup-bacon'};
export function resetOrava(w){const p=w.player;w.oravaOwner=p;w.oravaAttack=null;w.oravaTrail=[{x:p.x,y:p.y,grounded:p.grounded}];w.oravaDog={x:p.x-p.face*27,y:p.y,face:p.face,moving:false,grounded:p.grounded,wait:0};}
export function setOrava(w,enabled){enabled=!!enabled;if(!!w.oravaActive===enabled)return;w.oravaActive=enabled;w.player.attackActive=false;w.player.attackFrame=false;w.player.attackTimer=0;w.player.attackCooldown=0;w.player.animationVariant=-1;w.playerWeapon=null;w.projectiles=w.projectiles.filter(s=>!s.oravaStar&&!s.contact);w.effects=w.effects.filter(s=>!s.oravaBurst);resetOrava(w);}
export function advanceOravaAttack(w){const p=w.player,a=w.oravaAttack||(w.oravaAttack={age:0});p.attackFrame=true;w.animatePlayer(p.attackAction);w.friction();a.age++;p.attackTimer=Math.max(0,7-a.age);p.attackActive=a.age<7;w.playerWeapon=null;
 if(a.age===3){if(w.projectiles.filter(s=>s.oravaStar&&s.ttl>0).length<4)w.projectiles.push({oravaStar:true,ranged:true,sprite:182,x:p.x+p.face*19,y:p.y-(p.downTimer?8:18),face:p.face,vx:p.face*80,vy:0,ttl:52,damage:30});w.emit('oravaBell',{x:p.x,y:p.y});}
 if(!p.attackActive){p.attackCooldown=4;if(!p.platformGrip)p.vy+=p.attackAction===6?0:p.attackAction===3?-32:-48;}
}
export function updateOrava(w){if(!w.oravaActive)return;const p=w.player;if(!w.oravaDog||w.oravaOwner!==p){resetOrava(w);w.oravaOwner=p;}let dog=w.oravaDog,trail=w.oravaTrail,last=trail.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)>96){resetOrava(w);dog=w.oravaDog;trail=w.oravaTrail;last=trail[0];}
 if(Math.hypot(p.x-last.x,p.y-last.y)>=1)trail.push({x:p.x,y:p.y,grounded:p.grounded});while(trail.length>128)trail.shift();let length=0,target=trail[0];for(let i=trail.length-1;i>0;i--){length+=Math.hypot(trail[i].x-trail[i-1].x,trail[i].y-trail[i-1].y);if(length>=27){target=trail[i-1];break;}}
 if(trail.length===1)target={x:p.x-p.face*27,y:p.y,grounded:p.grounded};const dx=target.x-dog.x,dy=target.y-dog.y,dist=Math.hypot(dx,dy),speed=Math.min(6,dist);dog.moving=dist>.8;if(dog.moving){dog.x+=dx/(dist||1)*speed;dog.y+=dy/(dist||1)*speed;if(Math.abs(dx)>.3)dog.face=Math.sign(dx);dog.wait=0;}else dog.wait++;dog.grounded=target.grounded;
}
export function heroPose(w){const p=w.player,a=w.oravaAttack;if(w.deathTimer)return'defeat';if(p.invulnerable>=22)return'hurt';if(a&&p.attackFrame)return a.age<3?'attack-windup':a.age<5?'attack-release':'attack-recover';if(p.downTimer&&!w.alternate)return'crouch';if(!p.grounded)return p.vy<0?'jump':'fall';if(Math.abs(p.vx)>6)return'run-'+(Math.floor(w.frame/2)%4);return'idle-'+(Math.floor(w.frame/10)%2);}
export function dogPose(w){const d=w.oravaDog;if(!d.grounded)return'dog-fall';return d.moving?'trot-'+(Math.floor(w.frame/2)%4):d.wait>25?'sit':'idle-'+(Math.floor(w.frame/10)%2);}
export class OravaArt{
 static async load(base=new URL('../assets/orava/',import.meta.url)){const response=await fetch(new URL('manifest.json',base));if(!response.ok)throw Error('Orava art unavailable');const manifest=await response.json();if(manifest.version!==1)throw Error('Unsupported Orava art');const images={};await Promise.all(Object.entries(manifest.atlases).map(async([name,a])=>{if(!['hero','dog','effects','food'].includes(name)||a.file!==name+'.png')throw Error('Invalid Orava atlas');const im=new Image();im.src=new URL(a.file,base);await im.decode();if(im.naturalWidth!==a.width||im.naturalHeight!==a.height)throw Error('Invalid Orava dimensions');for(const f of Object.values(a.frames)){const[x,y,w,h]=f.rect;if([x,y,w,h].some(v=>!Number.isFinite(v))||x<0||y<0||w<=0||h<=0||x+w>a.width||y+h>a.height)throw Error('Invalid Orava frame');}images[name]=im;}));return new OravaArt(manifest,images);}
 portrait(c,scale){const f=this.manifest.atlases.hero.frames['idle-0'],r=f.rect;c.save();c.beginPath();c.arc(12*scale,189*scale,9*scale,0,Math.PI*2);c.clip();c.fillStyle='#443629';c.fillRect(2*scale,179*scale,20*scale,20*scale);c.drawImage(this.images.hero,r[0],r[1],r[2],r[3]*.52,2*scale,180*scale,20*scale,18*scale);c.restore();}
 constructor(manifest,images){this.manifest=manifest;this.images=images;}
 draw(c,atlas,id,x,y,flip,scale=1,size=null,flash=false){const a=this.manifest.atlases[atlas],f=a.frames[id];if(!f)return;const r=f.rect;let w=r[2]/a.pixelsPerUnit,h=r[3]/a.pixelsPerUnit;if(size){w=size.width;h=size.height;}c.save();c.beginPath();c.rect(0,0,320*scale,176*scale);c.clip();c.translate(x*scale,y*scale);if(flip)c.scale(-1,1);c.imageSmoothingEnabled=true;if(flash)c.globalAlpha=.6;c.drawImage(this.images[atlas],...r,-w/2*scale,-(atlas==='effects'?h/2:h)*scale,w*scale,h*scale);c.restore();}
}
